let input = String(params.input || params.text || params.b64 || '').trim();
if (!input) return { error: 'pass params.input (base64 string)' };
try {
  // Normalise URL-safe variant before decoding.
  const normalised = input.replace(/-/g, '+').replace(/_/g, '/');
  const pad = normalised.length % 4 === 0 ? normalised : normalised + '='.repeat(4 - (normalised.length % 4));
  const buf = Buffer.from(pad, 'base64');
  const decoded = buf.toString('utf-8');
  // Detect mostly-binary: > 5% control chars suggests this isn't text.
  const ctrl = [...decoded].filter((c) => c.charCodeAt(0) < 0x20 && c !== '\n' && c !== '\r' && c !== '\t').length;
  const looks_binary = decoded.length > 0 && ctrl / decoded.length > 0.05;
  return { decoded, bytes: buf.length, looks_binary };
} catch (e) {
  return { error: 'invalid base64: ' + e.message };
}
